import React, { useState, useEffect } from 'react';
import { AnimatePresence, motion } from 'framer-motion';

export type ToastType = 'success' | 'error' | 'info';

interface ToastMessage {
  id: string;
  type: ToastType;
  message: string;
  duration?: number;
}

let toastListener: ((toasts: ToastMessage[]) => void) | null = null;
let toasts: ToastMessage[] = [];

export const showToast = (message: string, type: ToastType = 'info', duration: number = 2000) => {
  if (type === 'info') {
    toasts = toasts.filter(t => t.type !== 'info');
  }

  const id = Date.now().toString() + Math.random();
  const finalDuration = type === 'info' ? 0 : duration;
  const newToast = { id, message, type, duration: finalDuration };
  
  toasts = [...toasts, newToast];
  toastListener?.([...toasts]);

  if (finalDuration > 0) {
    setTimeout(() => {
      removeToast(id);
    }, finalDuration);
  }
  
  return id;
};

export const removeToast = (id: string) => {
  toasts = toasts.filter(t => t.id !== id);
  toastListener?.([...toasts]);
};

export const clearInfoToasts = () => {
  toasts = toasts.filter(t => t.type !== 'info');
  toastListener?.([...toasts]);
};

export const ToastContainer = () => {
  const [currentToasts, setCurrentToasts] = useState<ToastMessage[]>([]);

  useEffect(() => {
    toastListener = setCurrentToasts;
    return () => { toastListener = null; };
  }, []);

  return (
    <div className="absolute top-28 left-1/2 -translate-x-1/2 z-[140] flex flex-col items-center pointer-events-none gap-3 w-full px-4">
      <AnimatePresence>
        {currentToasts.map(t => {
          let bgClass = '';
          let textClass = 'text-white';
          if (t.type === 'success') bgClass = 'bg-emerald-500 shadow-emerald-500/30 border border-emerald-400';
          else if (t.type === 'error') bgClass = 'bg-rose-500 shadow-rose-500/30 border border-rose-400';
          else {
            bgClass = 'bg-[#fdf5e6] border-2 border-[#e6d5b8] shadow-lg'; // Beige
            textClass = 'text-text-primary';
          }
          
          return (
            <motion.div
              key={t.id}
              initial={{ opacity: 0, y: -20, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: -20, scale: 0.95 }}
              onClick={() => {
                if (t.type !== 'info') removeToast(t.id);
              }}
              className={`px-5 py-3 rounded-2xl shadow-xl font-bold pointer-events-auto flex items-center justify-center text-center text-sm w-max max-w-full ${bgClass} ${textClass} ${t.type !== 'info' ? 'cursor-pointer' : ''}`}
            >
              {t.message}
            </motion.div>
          );
        })}
      </AnimatePresence>
    </div>
  );
};
