import React from 'react';
import { Player } from '../../types';
import { ImageUpload } from '../shared/ImageUpload';
import { Card } from '../ui/Card';

interface PlayerProfileProps {
  player: Player;
  onAvatarUpload: (dataUrl: string) => void;
}

/**
 * 玩家个人信息模块
 * 用于展示玩家的头像、姓名和身份标识
 * @param player - 玩家数据对象，包含玩家的所有信息
 * @param onAvatarUpload - 处理头像上传的回调函数
 */
export const PlayerProfile: React.FC<PlayerProfileProps> = ({ player, onAvatarUpload }) => {
  return (
    <Card className="rounded-3xl p-5 flex items-center gap-4 mb-4 relative overflow-hidden">
      {/* 玩家头像：展示玩家上传的图片或默认图片，点击可上传新头像 */}
      <ImageUpload 
        currentImage={player.avatar} 
        onUpload={onAvatarUpload}
        className="w-20 h-20 rounded-full border-4 border-white shadow-lg shrink-0"
      />
      <div className="flex flex-col justify-center">
        {/* 玩家姓名 */}
        <div className="text-xl font-bold text-text-primary">{player.name}</div>
        {/* 玩家身份标签，例如"学生会干事" */}
        <div className="text-xs font-medium text-pink-500 bg-pink-50 px-2 py-0.5 rounded-full w-fit mt-1">
          {player.identity}
        </div>
      </div>
    </Card>
  );
};
