/** 校规路径：校规/分类/标题 */
export function buildRulePathId(category: string, title: string): string {
  const safeCategory = String(category || '其他').trim() || '其他';
  const safeTitle = String(title || '').trim() || '未命名校规';
  return `${safeCategory}/${safeTitle}`;
}

