type MvuDataOption =
  | { type: 'message'; message_id: number | 'latest' }
  | { type: 'chat' };

type MvuRawData = {
  initialized_lorebooks?: string[] | Record<string, any>;
  stat_data?: Record<string, any>;
  [key: string]: any;
};

const MVU_LIST_KEYS = new Set(['性癖标签', '生效地点', '建筑活动', '活动环节', '成员']);

let ensureInitPromise: Promise<boolean> | null = null;
let lastReadOption: MvuDataOption = { type: 'chat' };
let lastGoodStatData: Record<string, any> | null = null;
let lastGoodScore = 0;

function isCampusScriptFrame(): boolean {
  const frame = window.frameElement as HTMLIFrameElement | null;
  if (frame?.dataset.campusScriptMounted === '1') return true;
  const name = frame?.id || frame?.getAttribute('data-script-id') || '';
  return /TH-script/i.test(name);
}

function isPlainObject(value: unknown): value is Record<string, any> {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

function unwrapMvuValue(value: any, key = ''): any {
  if (value == null) return value;

  if (MVU_LIST_KEYS.has(key) && Array.isArray(value)) {
    return value
      .filter(item => item !== '$__META_EXTENSIBLE__$')
      .map(item => unwrapMvuValue(item));
  }

  if (Array.isArray(value) && value.length === 2 && typeof value[1] === 'string' && !Array.isArray(value[0])) {
    return unwrapMvuValue(value[0], key);
  }

  if (Array.isArray(value)) {
    return value
      .filter(item => item !== '$__META_EXTENSIBLE__$')
      .map(item => unwrapMvuValue(item));
  }

  if (isPlainObject(value)) {
    return Object.fromEntries(Object.entries(value).map(([childKey, childValue]) => [childKey, unwrapMvuValue(childValue, childKey)]));
  }

  return value;
}

function omitMvuMeta<T extends Record<string, any>>(record: T | null | undefined): T {
  if (!isPlainObject(record)) {
    return {} as T;
  }
  return Object.fromEntries(
    Object.entries(record).filter(([key, value]) => key !== '$meta' && isPlainObject(value)),
  ) as T;
}

function asText(value: unknown): string {
  if (value == null) return '';
  if (typeof value === 'string') return value.trim();
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value) && value.length === 2 && typeof value[1] === 'string') {
    return asText(value[0]);
  }
  return '';
}

function asBoolean(value: unknown, fallback = true): boolean {
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return value !== 0;
  if (typeof value === 'string') {
    const text = value.trim().toLowerCase();
    if (['false', '0', 'no', 'off', '关闭', '否', '禁用', '未启用'].includes(text)) return false;
    if (['true', '1', 'yes', 'on', '开启', '是', '启用', '已启用'].includes(text)) return true;
  }
  if (Array.isArray(value) && value.length === 2) {
    return asBoolean(value[0], fallback);
  }
  return fallback;
}

function asStringList(value: unknown): string[] {
  if (value == null || value === '') return [];
  if (typeof value === 'string') {
    return value
      .split(/[,，、;；/|]+/)
      .map(item => item.trim())
      .filter(Boolean);
  }
  if (!Array.isArray(value)) return [];
  return value
    .filter(item => item !== '$__META_EXTENSIBLE__$')
    .flatMap(item => asStringList(item))
    .filter(Boolean);
}

function looksLikeRule(value: unknown): value is Record<string, any> {
  if (!isPlainObject(value)) return false;
  return ['标题', '内容', '分类', '是否启用', '生效地点', 'title', 'content', 'category'].some(key => key in value);
}

function looksLikeNestedRuleBucket(value: unknown): value is Record<string, any> {
  if (!isPlainObject(value)) return false;
  if (looksLikeRule(value)) return false;
  return Object.entries(value).some(([key, child]) => key !== '$meta' && looksLikeRule(child));
}

export function parseMvuRules(raw: unknown): Record<string, MvuRule> {
  const source = unwrapMvuValue(raw, '校规');
  const result: Record<string, MvuRule> = {};

  const pushRule = (id: string, data: Record<string, any>, fallbackCategory = '其他') => {
    const title = asText(data.标题 ?? data.title) || id.split('/').pop() || id;
    const content = asText(data.内容 ?? data.content);
    if (!title && !content) return;
    const category = asText(data.分类 ?? data.category) || fallbackCategory || '其他';
    const uniqueId = result[id] ? `${id}-${Object.keys(result).length + 1}` : id;
    result[uniqueId] = {
      标题: title,
      内容: content,
      分类: category,
      是否启用: asBoolean(data.是否启用 ?? data.enabled, true),
      生效地点: asStringList(data.生效地点 ?? data.locationNames ?? data.地点),
    };
  };

  if (Array.isArray(source)) {
    source.forEach((item, index) => {
      if (looksLikeRule(item)) {
        const title = asText(item.标题) || `rule-${index + 1}`;
        const category = asText(item.分类) || '其他';
        pushRule(buildRulePathId(category, title), item, category);
      }
    });
    return result;
  }

  if (!isPlainObject(source)) {
    return result;
  }

  Object.entries(source).forEach(([key, value]) => {
    if (key === '$meta') return;

    // 新结构：校规 / 分类 / 标题
    if (looksLikeNestedRuleBucket(value)) {
      Object.entries(value).forEach(([titleKey, childValue]) => {
        if (titleKey === '$meta' || !looksLikeRule(childValue)) return;
        const title = asText(childValue.标题 ?? childValue.title) || titleKey;
        pushRule(buildRulePathId(key, title), { ...childValue, 标题: title, 分类: key }, key);
      });
      return;
    }

    // 旧结构：校规 / life-1 / {标题,内容,分类...}
    if (looksLikeRule(value)) {
      const title = asText(value.标题 ?? value.title) || key;
      const category = asText(value.分类 ?? value.category) || '其他';
      // 兼容旧 ID，同时尽量提供可读路径 ID
      pushRule(key.includes('/') ? key : buildRulePathId(category, title), value, category);
      return;
    }

    if (Array.isArray(value)) {
      value.forEach((item, index) => {
        if (!looksLikeRule(item)) return;
        const title = asText(item.标题) || `${key}-${index + 1}`;
        pushRule(buildRulePathId(key, title), { 分类: key, ...item }, key);
      });
    }
  });

  return result;
}

function looksLikeChatGroup(value: unknown): value is Record<string, any> {
  if (!isPlainObject(value)) return false;
  return ['群名', '简介', '成员', 'name', 'members', 'summary'].some(key => key in value);
}

export function parseMvuChatGroups(raw: unknown): Record<string, MvuChatGroup> {
  const source = unwrapMvuValue(raw, '聊天群组');
  const result: Record<string, MvuChatGroup> = {};

  const pushGroup = (id: string, data: Record<string, any>) => {
    const name = asText(data.群名 ?? data.name) || id;
    const members = asStringList(data.成员 ?? data.members ?? data.成员名单);
    if (!name && !members.length) return;
    const uniqueId = result[id] ? `${id}-${Object.keys(result).length + 1}` : id;
    result[uniqueId] = {
      群名: name,
      简介: asText(data.简介 ?? data.summary ?? data.描述),
      成员: members,
    };
  };

  if (Array.isArray(source)) {
    source.forEach((item, index) => {
      if (looksLikeChatGroup(item)) {
        pushGroup(asText(item.群名) || `group-${index + 1}`, item);
      }
    });
    return result;
  }

  if (!isPlainObject(source)) {
    return result;
  }

  Object.entries(source).forEach(([key, value]) => {
    if (key === '$meta') return;
    if (looksLikeChatGroup(value)) {
      pushGroup(key, value);
    }
  });

  return result;
}

function getCampusBuildingsFromRoot(root: Record<string, any> | null | undefined): Record<string, any> {
  return omitMvuMeta(unwrapMvuValue(root?.校园建筑, '校园建筑'));
}

function hasMeaningfulStatData(mvuData: MvuRawData | null | undefined): boolean {
  const root = mvuData?.stat_data;
  return isPlainObject(root) && Object.keys(root).length > 0;
}

function getStatRoot(mvuData: MvuRawData | null | undefined): Record<string, any> {
  if (!hasMeaningfulStatData(mvuData)) return {};
  return unwrapMvuValue(mvuData!.stat_data) as Record<string, any>;
}

function scoreStatRoot(root: Record<string, any> | null | undefined): number {
  if (!isPlainObject(root) || !Object.keys(root).length) return 0;
  let score = Object.keys(root).length;
  const playerName = asText(root?.玩家?.姓名);
  if (playerName) score += 80;
  if (root?.时间 && (root.时间.小时 != null || root.时间.分钟 != null)) score += 20;
  score += Object.keys(omitMvuMeta(root.角色)).length * 8;
  score += Object.keys(parseMvuRules(root.校规)).length * 4;
  score += Object.keys(parseMvuChatGroups(root.聊天群组)).length * 3;
  score += Object.keys(omitMvuMeta(root.校园建筑)).length;
  return score;
}

function scoreStatData(mvuData: MvuRawData | null | undefined): number {
  return scoreStatRoot(getStatRoot(mvuData));
}

function isDisplayReady(root: Record<string, any> | null | undefined): boolean {
  if (!isPlainObject(root)) return false;
  if (asText(root?.玩家?.姓名)) return true;
  if (Object.keys(omitMvuMeta(root.角色)).length > 0) return true;
  if (Object.keys(parseMvuRules(root.校规)).length > 0) return true;
  if (Object.keys(parseMvuChatGroups(root.聊天群组)).length > 0) return true;
  if (Object.keys(omitMvuMeta(root.校园建筑)).length > 0) return true;
  return false;
}

function isWeakerStatRoot(next: Record<string, any>, prev: Record<string, any> | null): boolean {
  if (!prev || !isDisplayReady(prev)) return false;
  if (!isDisplayReady(next)) return true;
  const prevChars = Object.keys(omitMvuMeta(prev.角色)).length;
  const nextChars = Object.keys(omitMvuMeta(next.角色)).length;
  const prevRules = Object.keys(parseMvuRules(prev.校规)).length;
  const nextRules = Object.keys(parseMvuRules(next.校规)).length;
  const prevGroups = Object.keys(parseMvuChatGroups(prev.聊天群组)).length;
  const nextGroups = Object.keys(parseMvuChatGroups(next.聊天群组)).length;
  const prevPlayer = asText(prev?.玩家?.姓名);
  const nextPlayer = asText(next?.玩家?.姓名);
  if (prevPlayer && !nextPlayer) return true;
  if (prevChars > 0 && nextChars === 0) return true;
  if (prevRules > 0 && nextRules === 0) return true;
  if (prevGroups > 0 && nextGroups === 0) return true;
  return scoreStatRoot(next) + 8 < lastGoodScore;
}

function getMvuApi(): any | null {
  const local = (window as any).Mvu;
  if (local?.getMvuData) return local;
  try {
    const parentMvu = (window.parent as any)?.Mvu;
    if (parentMvu?.getMvuData) return parentMvu;
  } catch {
    // ignore cross-origin
  }
  return null;
}

function optionKey(option: MvuDataOption): string {
  if (option.type === 'chat') return 'chat';
  return `message:${option.message_id}`;
}

function listReadOptions(): MvuDataOption[] {
  const options: MvuDataOption[] = [{ type: 'message', message_id: 'latest' }, { type: 'chat' }];
  try {
    if (typeof getLastMessageId === 'function') {
      const lastId = getLastMessageId();
      options.unshift({ type: 'message', message_id: lastId });
      if (typeof lastId === 'number' && lastId > 0) {
        options.push({ type: 'message', message_id: lastId - 1 });
      }
    }
  } catch {
    // 全局脚本 iframe 仍可使用 latest
  }
  if (!isCampusScriptFrame()) {
    try {
      if (typeof getCurrentMessageId === 'function') {
        options.unshift({ type: 'message', message_id: getCurrentMessageId() });
      }
    } catch {
      // ignore
    }
  }

  const seen = new Set<string>();
  return options.filter(option => {
    const key = optionKey(option);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function readMvuData(option: MvuDataOption): MvuRawData | null {
  try {
    const mvu = getMvuApi();
    if (!mvu) return null;
    return (mvu.getMvuData(option) as MvuRawData) ?? null;
  } catch (error) {
    console.warn('[MVU] 读取变量失败:', option, error);
    return null;
  }
}

function getMvuDataOption(): MvuDataOption {
  return lastReadOption;
}

function getRawMvuData(): MvuRawData | null {
  const mvu = getMvuApi();
  if (!mvu) return null;

  let best: MvuRawData | null = null;
  let bestScore = -1;
  let bestOption: MvuDataOption = lastReadOption;

  for (const option of listReadOptions()) {
    const data = readMvuData(option);
    const score = scoreStatData(data);
    if (score > bestScore) {
      best = data;
      bestScore = score;
      bestOption = option;
    }
  }

  if (bestScore > 0) {
    lastReadOption = bestOption;
  }
  return best;
}

function resetDisplayedStatCache() {
  lastGoodStatData = null;
  lastGoodScore = 0;
}

function getDisplayStatData(): Record<string, any> {
  const raw = getRawMvuData();
  const next = getStatRoot(raw);
  const nextScore = scoreStatRoot(next);

  if (nextScore > 0 && !isWeakerStatRoot(next, lastGoodStatData)) {
    lastGoodStatData = next;
    lastGoodScore = Math.max(lastGoodScore, nextScore);
    return next;
  }

  if (lastGoodStatData) {
    return lastGoodStatData;
  }

  return next;
}

function hasCampusBuildings(mvuData: MvuRawData | null | undefined): boolean {
  return Object.keys(getCampusBuildingsFromRoot(mvuData?.stat_data)).length > 0;
}

function getChatDataRoot(): Record<string, any> {
  return getDisplayStatData();
}

function listCandidateWorldbookNames(): string[] {
  const names = new Set<string>();
  try {
    getWorldbookNames().forEach(name => names.add(name));
  } catch {
    // ignore
  }
  try {
    getGlobalWorldbookNames().forEach(name => names.add(name));
  } catch {
    // ignore
  }
  try {
    const bound = getCharWorldbookNames('current');
    if (bound.primary) names.add(bound.primary);
    bound.additional.forEach(name => names.add(name));
  } catch {
    // ignore
  }
  try {
    const chatWorldbook = getChatWorldbookName('current');
    if (chatWorldbook) names.add(chatWorldbook);
  } catch {
    // ignore
  }
  return [...names];
}

function isInitVarEntryName(name: string): boolean {
  return /\[?\s*initvar\s*\]?/i.test(name) || /变量初始化/.test(name);
}

function parseSimpleYaml(text: string): Record<string, any> | null {
  const lines = text
    .replace(/^\uFEFF/, '')
    .split(/\r?\n/)
    .map(line => line.replace(/\t/g, '  '))
    .filter(line => line.trim() && !line.trim().startsWith('#'));

  if (!lines.length) return null;

  type Frame = { indent: number; container: any };
  const root: Record<string, any> = {};
  const stack: Frame[] = [{ indent: -1, container: root }];

  const parseScalar = (raw: string): any => {
    const value = raw.trim();
    if (!value) return '';
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
      return value.slice(1, -1);
    }
    if (value === '[]') return [];
    if (value === '{}' ) return {};
    if (value === 'true') return true;
    if (value === 'false') return false;
    if (value === 'null' || value === '~') return null;
    if (/^-?\d+(\.\d+)?$/.test(value)) return Number(value);
    return value;
  };

  for (const line of lines) {
    const indent = line.match(/^ */)?.[0].length ?? 0;
    const content = line.trim();

    while (stack.length > 1 && indent <= stack[stack.length - 1].indent) {
      stack.pop();
    }
    const parent = stack[stack.length - 1].container;

    if (content.startsWith('- ')) {
      if (!Array.isArray(parent)) {
        return null;
      }
      const itemText = content.slice(2).trim();
      if (!itemText) {
        const obj = {};
        parent.push(obj);
        stack.push({ indent, container: obj });
        continue;
      }
      if (itemText.includes(':')) {
        const idx = itemText.indexOf(':');
        const key = itemText.slice(0, idx).trim();
        const rest = itemText.slice(idx + 1).trim();
        const obj: Record<string, any> = {};
        if (rest) {
          obj[key] = parseScalar(rest);
          parent.push(obj);
        } else {
          obj[key] = {};
          parent.push(obj);
          stack.push({ indent, container: obj });
          stack.push({ indent: indent + 2, container: obj[key] });
        }
      } else {
        parent.push(parseScalar(itemText));
      }
      continue;
    }

    const colon = content.indexOf(':');
    if (colon < 0) return null;
    const key = content.slice(0, colon).trim();
    const rest = content.slice(colon + 1).trim();
    if (!(parent && typeof parent === 'object' && !Array.isArray(parent))) {
      return null;
    }
    if (!rest) {
      // Lookahead: next deeper line starting with `-` means array, otherwise object
      const next = lines.find(candidate => {
        const nextIndent = candidate.match(/^ */)?.[0].length ?? 0;
        return nextIndent > indent;
      });
      const nextContent = next?.trim() || '';
      if (nextContent.startsWith('- ')) {
        parent[key] = [];
        stack.push({ indent, container: parent[key] });
      } else {
        parent[key] = {};
        stack.push({ indent, container: parent[key] });
      }
      continue;
    }
    parent[key] = parseScalar(rest);
  }

  return Object.keys(root).length ? root : null;
}

function tryParseInitContent(content: string): Record<string, any> | null {
  const text = content.replace(/^\uFEFF/, '').trim();
  if (!text) return null;

  try {
    const parsed = JSON.parse(text);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      return parsed as Record<string, any>;
    }
  } catch {
    // fallthrough
  }

  try {
    const yaml = (window as any).YAML || (window as any).jsyaml || (window.parent as any)?.YAML || (window.parent as any)?.jsyaml;
    if (yaml?.parse) {
      const parsed = yaml.parse(text);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
        return parsed as Record<string, any>;
      }
    }
  } catch {
    // ignore
  }

  try {
    return parseSimpleYaml(text);
  } catch (error) {
    console.warn('[MVU] 简易 YAML 解析失败:', error);
    return null;
  }
}

async function loadInitVarFromWorldbooks(): Promise<{ data: Record<string, any>; source: string } | null> {
  const worldbooks = listCandidateWorldbookNames();
  console.info('[MVU] 扫描世界书以寻找 initvar:', worldbooks);

  for (const worldbookName of worldbooks) {
    try {
      const entries = await getWorldbook(worldbookName);
      const initEntries = entries
        .filter(entry => isInitVarEntryName(entry.name))
        // initvar 条目常被标注为“勿开”，仍然允许作为变量初始化来源
        .sort((a, b) => Number(b.enabled) - Number(a.enabled));

      console.info(
        `[MVU] 世界书「${worldbookName}」匹配 initvar 条目:`,
        initEntries.map(item => `${item.name}${item.enabled ? '' : '(disabled)'}`),
      );

      for (const entry of initEntries) {
        const parsed = tryParseInitContent(entry.content || '');
        if (parsed && Object.keys(parsed).length) {
          const source = `${worldbookName} / ${entry.name}`;
          console.info(`[MVU] 已从世界书「${source}」解析到 initvar，顶层字段:`, Object.keys(parsed));
          return { data: parsed, source };
        }
        console.warn(`[MVU] 条目「${entry.name}」内容无法解析为对象`);
      }
    } catch (error) {
      console.warn(`[MVU] 读取世界书「${worldbookName}」失败:`, error);
    }
  }
  return null;
}

async function writeStatDataPatch(patch: Record<string, any>, reason: string): Promise<boolean> {
  const mvu = getMvuApi();
  if (!mvu?.replaceMvuData) {
    return false;
  }
  const current = getRawMvuData() ?? { stat_data: {} };
  const next: MvuRawData = {
    ...current,
    stat_data: {
      ...(typeof current.stat_data === 'object' && current.stat_data ? current.stat_data : {}),
      ...patch,
    },
  };
  await mvu.replaceMvuData(next, getMvuDataOption());
  console.info(`[MVU] 已写入变量补丁（${reason}）:`, Object.keys(patch));
  return true;
}

async function ensureCampusBuildingsAvailable(): Promise<boolean> {
  let raw = getRawMvuData();
  if (hasCampusBuildings(raw)) {
    return true;
  }

  const init = await loadInitVarFromWorldbooks();
  const buildingsFromInit = getCampusBuildingsFromRoot(init?.data);
  if (Object.keys(buildingsFromInit).length) {
    const patch =
      !hasMeaningfulStatData(raw) && init?.data
        ? init.data
        : { 校园建筑: buildingsFromInit };
    await writeStatDataPatch(patch, init?.source || 'initvar.校园建筑');
    raw = getRawMvuData();
    if (hasCampusBuildings(raw)) {
      return true;
    }
  }

  // 世界书读不到或解析失败时，用内置建筑表兜底，保证始发地可选
  await writeStatDataPatch({ 校园建筑: { $meta: { extensible: true }, ...FALLBACK_CAMPUS_BUILDINGS } }, '内置校园建筑兜底');
  return hasCampusBuildings(getRawMvuData()) || true;
}

/**
 * 新开聊天时，MVU 的 initvar 有时还未落到 chat 变量里；
 * 也可能只初始化了部分字段、缺少「校园建筑」。
 * 入学界面会主动补齐。
 */
export async function ensureMvuStatDataInitialized(): Promise<boolean> {
  if (ensureInitPromise) {
    return ensureInitPromise;
  }

  ensureInitPromise = (async () => {
    const mvu = getMvuApi();
    if (!mvu) {
      console.warn('[MVU] Mvu 框架未就绪，无法初始化变量；将使用内置建筑列表兜底');
      return true;
    }

    let raw = getRawMvuData();
    if (hasCampusBuildings(raw)) {
      return true;
    }

    if (!hasMeaningfulStatData(raw)) {
      console.info('[MVU] 当前上下文 stat_data 为空，尝试 reloadInitVar...');
      try {
        const ok = await mvu.reloadInitVar(raw ?? mvu.getMvuData({ type: 'chat' }));
        if (ok) {
          raw = getRawMvuData();
          if (hasCampusBuildings(raw)) {
            console.info('[MVU] reloadInitVar 成功，已包含校园建筑');
            return true;
          }
          if (hasMeaningfulStatData(raw)) {
            console.warn('[MVU] reloadInitVar 后仍缺少校园建筑，继续兜底补齐');
          }
        }
      } catch (error) {
        console.warn('[MVU] reloadInitVar 失败:', error);
      }
    } else {
      console.warn('[MVU] stat_data 已有数据，但缺少校园建筑，开始补齐');
    }

    return ensureCampusBuildingsAvailable();
  })().finally(() => {
    window.setTimeout(() => {
      ensureInitPromise = null;
    }, 1000);
  });

  return ensureInitPromise;
}

export async function reloadMvuCampusBuildings(buildings: Record<string, any>): Promise<boolean> {
  resetDisplayedStatCache();
  const mvu = getMvuApi();
  const nextBuildings = { $meta: { extensible: true }, ...buildings };

  if (mvu?.reloadInitVar) {
    try {
      const current = getRawMvuData() ?? mvu.getMvuData({ type: 'chat' });
      const ok = await mvu.reloadInitVar(current);
      if (ok) {
        await writeStatDataPatch({ 校园建筑: nextBuildings }, '入学档案切换校园布局后 reloadInitVar');
        resetDisplayedStatCache();
        return true;
      }
    } catch (error) {
      console.warn('[MVU] 切换校园布局后 reloadInitVar 失败，改为直接写入建筑:', error);
    }
  }

  const patched = await writeStatDataPatch({ 校园建筑: nextBuildings }, '入学档案切换校园布局');
  resetDisplayedStatCache();
  return patched;
}

// 从当前上下文的 MVU 变量读取数据（消息楼层优先，全局脚本回退到 chat）
export function getMvuVariable(path: string): any {
  try {
    const root = getChatDataRoot();
    if (!Object.keys(root).length) {
      return null;
    }
    return _.get(root, path);
  } catch (error) {
    console.error(`[MVU] 读取变量 "${path}" 时出错:`, error);
    return null;
  }
}

// 设置当前上下文的 MVU 变量
export async function setMvuVariable(path: string, value: any): Promise<void> {
  try {
    await ensureMvuStatDataInitialized();
    const option = getMvuDataOption();
    const mvuData = getRawMvuData();
    if (!mvuData || !mvuData.stat_data || typeof mvuData.stat_data !== 'object') {
      console.warn('[MVU] 当前上下文没有可用的 stat_data');
      return;
    }

    _.set(mvuData.stat_data, path, value);
    await (window as any).Mvu.replaceMvuData(mvuData, option);
  } catch (error) {
    console.error(`[MVU] 设置变量 "${path}" 时出错:`, error);
  }
}

// Hook: 监听 MVU 变量变化
export function useMvuVariable<T = any>(path: string, defaultValue: T): [T, (value: T) => void] {
  const [value, setValue] = useState<T>(() => {
    const mvuValue = getMvuVariable(path);
    return mvuValue !== null && mvuValue !== undefined ? mvuValue : defaultValue;
  });

  useEffect(() => {
    let cancelled = false;

    const syncValue = () => {
      const newValue = getMvuVariable(path);
      if (newValue !== null && newValue !== undefined) {
        setValue(newValue);
      }
    };

    void (async () => {
      await ensureMvuStatDataInitialized();
      if (!cancelled) syncValue();
    })();

    const timer = window.setInterval(syncValue, 800);
    const refresh = () => {
      if (!cancelled) syncValue();
    };
    try {
      eventOn(tavern_events.MESSAGE_RECEIVED, refresh);
      eventOn(tavern_events.MESSAGE_UPDATED, refresh);
      eventOn(tavern_events.CHAT_CHANGED, refresh);
      const mvu = getMvuApi();
      if (mvu?.events?.VARIABLE_UPDATE_ENDED) {
        eventOn(mvu.events.VARIABLE_UPDATE_ENDED, refresh);
      }
    } catch {
      // ignore
    }
    return () => {
      cancelled = true;
      window.clearInterval(timer);
    };
  }, [path]);

  const updateValue = (newValue: T) => {
    setValue(newValue);
    void setMvuVariable(path, newValue);
  };

  return [value, updateValue];
}

// 获取完整 MVU 数据（始终返回对象，避免空值崩溃）
export function getFullMvuData(): Partial<MvuData> {
  return getChatDataRoot() as Partial<MvuData>;
}

export function useMvuSnapshot(): Partial<MvuData> {
  const [data, setData] = useState<Partial<MvuData>>(() => getFullMvuData());

  useEffect(() => {
    let cancelled = false;
    const sync = () => {
      const next = getFullMvuData();
      setData(prev => {
        if (_.isEqual(prev, next)) return prev;
        if (isDisplayReady(prev) && !isDisplayReady(next)) return prev;
        return next;
      });
    };

    void (async () => {
      await ensureMvuStatDataInitialized();
      if (!cancelled) sync();
    })();

    const timer = window.setInterval(sync, 800);
    const refresh = () => {
      if (!cancelled) sync();
    };
    const refreshChat = () => {
      resetDisplayedStatCache();
      refresh();
    };
    try {
      eventOn(tavern_events.MESSAGE_RECEIVED, refresh);
      eventOn(tavern_events.MESSAGE_UPDATED, refresh);
      eventOn(tavern_events.CHAT_CHANGED, refreshChat);
      const mvu = getMvuApi();
      if (mvu?.events?.VARIABLE_UPDATE_ENDED) {
        eventOn(mvu.events.VARIABLE_UPDATE_ENDED, refresh);
      }
    } catch {
      // ignore
    }

    return () => {
      cancelled = true;
      window.clearInterval(timer);
    };
  }, []);

  return data;
}

export function getCampusBuildingNames(): string[] {
  const buildings = getCampusBuildingsFromRoot(getFullMvuData());
  const names = Object.keys(buildings);
  return names.length ? names : getFallbackCampusBuildingNames();
}

export function useCampusBuildings(): { names: string[]; loading: boolean; ready: boolean } {
  const [names, setNames] = useState<string[]>(() => getCampusBuildingNames());
  const [loading, setLoading] = useState(() => Object.keys(getCampusBuildingsFromRoot(getFullMvuData())).length === 0);
  const [ready, setReady] = useState(() => names.length > 0);

  useEffect(() => {
    let cancelled = false;

    const sync = () => {
      const next = getCampusBuildingNames();
      if (next.length) {
        setReady(true);
        setLoading(false);
      }
      setNames(prev => (_.isEqual(prev, next) ? prev : next));
    };

    void (async () => {
      setLoading(true);
      await ensureMvuStatDataInitialized();
      if (cancelled) return;
      sync();
      setLoading(false);
    })();

    const timer = window.setInterval(sync, 800);
    return () => {
      cancelled = true;
      window.clearInterval(timer);
    };
  }, []);

  return { names, loading, ready };
}

function asFiniteNumber(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string' && value.trim()) {
    const next = Number(value);
    return Number.isFinite(next) ? next : null;
  }
  if (Array.isArray(value) && value.length === 2) {
    return asFiniteNumber(value[0]);
  }
  return null;
}

function readMvuTimeValue(source: Record<string, any> | null | undefined, key: string, aliases: string[] = []): number | null {
  if (!isPlainObject(source)) return null;
  const keys = [key, ...aliases];
  for (const item of keys) {
    const next = asFiniteNumber(unwrapMvuValue(source[item], item));
    if (next != null) return next;
  }
  return null;
}

export function getMvuStartTime(fallback: {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
}): {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
} {
  const time = unwrapMvuValue(getChatDataRoot()?.时间, '时间');
  const year = readMvuTimeValue(time, '年', ['year']);
  const month = readMvuTimeValue(time, '月', ['month']);
  const day = readMvuTimeValue(time, '日', ['day']);
  const hour = readMvuTimeValue(time, '小时', ['hour']);
  const minute = readMvuTimeValue(time, '分钟', ['minute']);
  if (year == null && month == null && day == null && hour == null && minute == null) {
    return fallback;
  }
  const nextYear = year ?? fallback.year;
  const nextMonth = Math.min(12, Math.max(1, Math.round(month ?? fallback.month)));
  const lastDay = new Date(nextYear, nextMonth, 0).getDate();
  return {
    year: nextYear,
    month: nextMonth,
    day: Math.min(lastDay, Math.max(1, Math.round(day ?? fallback.day))),
    hour: Math.min(23, Math.max(0, Math.round(hour ?? fallback.hour))),
    minute: Math.min(59, Math.max(0, Math.round(minute ?? fallback.minute))),
  };
}

export function formatMvuTime(time: MvuTime): string {
  const hour = Number(time?.小时);
  const minute = Number(time?.分钟);
  if (!Number.isFinite(hour) || !Number.isFinite(minute)) return '--:--';
  return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
}

// 格式化日期显示
export function formatMvuDate(time: MvuTime): string {
  const weekdays = ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六'];
  return `${time.月}月${time.日}日 ${weekdays[time.星期]}`;
}

// 格式化天气显示
export function formatMvuWeather(weather: MvuWeather): string {
  return `${weather.温度}°C ${weather.天气描述}`;
}
