import { DEFAULT_IDENTITIES, IdentityOption } from './constants';

const CUSTOM_IDENTITY_KEY = 'campus-app-custom-identities';

function getStorage(): Storage | null {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

export function loadCustomIdentities(): IdentityOption[] {
  const storage = getStorage();
  if (!storage) return [];
  try {
    const raw = storage.getItem(CUSTOM_IDENTITY_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as IdentityOption[];
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter(item => item && typeof item.name === 'string' && item.name.trim())
      .map(item => ({
        id: item.id || `custom-${item.name}`,
        name: item.name.trim(),
        description: String(item.description || '').trim(),
        custom: true,
      }));
  } catch {
    return [];
  }
}

export function saveCustomIdentities(identities: IdentityOption[]) {
  const storage = getStorage();
  if (!storage) return;
  try {
    storage.setItem(CUSTOM_IDENTITY_KEY, JSON.stringify(identities));
  } catch {
    // ignore quota / private mode
  }
}

export function loadAllIdentities(): IdentityOption[] {
  const custom = loadCustomIdentities();
  const usedIds = new Set(DEFAULT_IDENTITIES.map(item => item.id));
  const extras = custom.filter(item => {
    if (usedIds.has(item.id)) return false;
    usedIds.add(item.id);
    return true;
  });
  return [...DEFAULT_IDENTITIES, ...extras];
}

export function deleteCustomIdentity(id: string): boolean {
  const current = loadCustomIdentities();
  const next = current.filter(item => item.id !== id);
  if (next.length === current.length) return false;
  saveCustomIdentities(next);
  return true;
}

export function upsertCustomIdentities(incoming: IdentityOption[]): number {
  const current = loadCustomIdentities();
  const byId = new Map(current.map(item => [item.id, item]));
  let written = 0;
  for (const item of incoming) {
    const name = String(item?.name || '').trim();
    if (!name) continue;
    const id = String(item.id || '').trim() || `custom-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;
    byId.set(id, {
      id,
      name,
      description: String(item.description || '').trim(),
      custom: true,
    });
    written += 1;
  }
  saveCustomIdentities([...byId.values()]);
  return written;
}

export function addCustomIdentity(name: string, description: string): IdentityOption {
  const identity: IdentityOption = {
    id: `custom-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
    name: name.trim(),
    description: description.trim(),
    custom: true,
  };
  const next = [...loadCustomIdentities(), identity];
  saveCustomIdentities(next);
  return identity;
}
