export function fillTavernInput(text: string): boolean {
  const value = text.trim();
  if (!value) return false;

  const docs: Document[] = [document];
  try {
    if (window.parent && window.parent !== window) {
      docs.unshift(window.parent.document);
    }
  } catch {
    // ignore
  }

  for (const doc of docs) {
    const textarea =
      (doc.getElementById('send_textarea') as HTMLTextAreaElement | null) ||
      (doc.querySelector('#send_textarea, textarea[name="send_textarea"], #chat-input, textarea') as HTMLTextAreaElement | null);
    if (!textarea) continue;

    const existing = String(textarea.value || '').replace(/\s+$/, '');
    const next = existing ? `${existing}\n${value}` : value;

    const proto = window.HTMLTextAreaElement?.prototype;
    const setter = proto && Object.getOwnPropertyDescriptor(proto, 'value')?.set;
    if (setter) {
      setter.call(textarea, next);
    } else {
      textarea.value = next;
    }
    textarea.dispatchEvent(new Event('input', { bubbles: true }));
    textarea.dispatchEvent(new Event('change', { bubbles: true }));
    textarea.focus();
    textarea.setSelectionRange(next.length, next.length);
    return true;
  }

  return false;
}
