import React, { useState, useEffect, useRef } from 'react';
import { SchoolRule, CampusBuilding } from '../../types';
import { Card } from '../ui/Card';
import { Edit3, Trash2, Power, PowerOff, AlertCircle, MapPin } from 'lucide-react';
import { AnimatePresence, motion } from 'framer-motion';
import { useDraggableScroll } from '../../hooks/useDraggableScroll';

export interface RuleCardProps {
  rule: SchoolRule;
  buildings: CampusBuilding[];
  onToggle?: (rule: SchoolRule) => void;
  onEdit?: (rule: SchoolRule) => void;
  onDelete?: (id: string) => void;
}

export const RuleCard: React.FC<RuleCardProps> = ({ rule, buildings, onToggle, onEdit, onDelete }) => {
  const [popoverOpen, setPopoverOpen] = useState(false);
  const dragProps = useDraggableScroll<HTMLDivElement>();
  const popoverRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent | TouchEvent) => {
      if (popoverRef.current && !popoverRef.current.contains(e.target as Node)) {
        setPopoverOpen(false);
      }
    };
    if (popoverOpen) {
      document.addEventListener('mousedown', handleClickOutside);
      document.addEventListener('touchstart', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('touchstart', handleClickOutside);
    };
  }, [popoverOpen]);

  const checkLocationsExist = (locationNames?: string[]) => {
    if (!locationNames || locationNames.length === 0) return true;
    if (locationNames.includes('全校')) return true;
    return locationNames.every(name => buildings.some(b => b.name === name));
  };

  const hasLocations = rule.locationNames && rule.locationNames.length > 0;
  const locationsExist = checkLocationsExist(rule.locationNames);
  const showError = hasLocations && !locationsExist;
  
  const isGlobal = !rule.locationNames || rule.locationNames.length === 0 || rule.locationNames.includes('全校');
  const displayLocations = isGlobal ? ['全校'] : rule.locationNames!;

  return (
    <Card className={`transition-all ${!rule.enabled || rule.pendingAction === 'delete' ? 'opacity-70 grayscale-[0.3]' : ''} overflow-visible relative flex flex-col h-48 p-4`}>
      <div className="flex justify-between items-center mb-2 shrink-0">
        <h3 className={`font-bold text-text-primary text-base truncate flex-1 pr-2 ${rule.pendingAction === 'delete' ? 'line-through' : ''}`}>{rule.title}</h3>
        <div className="flex gap-2 items-center shrink-0">
          {showError && (
             <div className="flex items-center text-rose-500 text-xs font-bold gap-1" title="没有对应建筑">
               <AlertCircle className="w-3.5 h-3.5" />
             </div>
          )}
          {rule.pendingUpdate && (
            <div className="text-[10px] shrink-0 font-bold px-2 py-0.5 rounded-full border bg-amber-50 text-amber-600 border-amber-200">
              待更新
            </div>
          )}
          <div className={`text-[10px] shrink-0 font-bold px-2 py-0.5 rounded-full border ${rule.enabled ? 'bg-green-50 text-green-600 border-green-200' : 'bg-gray-100 text-text-secondary border-border-default'}`}>
            {rule.enabled ? '已开启' : '已关闭'}
          </div>
        </div>
      </div>
      
      <div 
        className="text-sm text-text-secondary mb-2 leading-relaxed mt-1 flex-1 overflow-y-auto overflow-x-hidden hide-scrollbar cursor-grab active:cursor-grabbing touch-none"
        {...dragProps} ref={dragProps.ref}
      >
        <div className="pointer-events-auto">
          {rule.content}
        </div>
      </div>
      
      <div className="flex items-center justify-between gap-2 pt-2 border-t border-border-default shrink-0">
        {/* Left: Location pill & popover */}
        <div className="relative shrink-0" ref={popoverRef}>
          <div 
            className="text-xs font-bold text-pink-500 flex items-center justify-center gap-1 bg-pink-50 hover:bg-pink-100 transition-colors px-2 py-1 rounded-full border border-pink-100 w-20 cursor-pointer overflow-hidden shadow-2xs"
            onClick={(e) => {
              e.stopPropagation();
              setPopoverOpen(!popoverOpen);
            }}
            title="点击查看生效地点"
          >
            <MapPin className="w-3 h-3 shrink-0 text-pink-500" />
            <div className="overflow-hidden whitespace-nowrap w-full flex items-center">
              <div className={`inline-block ${displayLocations.join('、').length > 3 ? 'animate-marquee-slow' : ''}`}>
                {displayLocations.join('、')}
                {displayLocations.join('、').length > 3 && <span className="ml-4">{displayLocations.join('、')}</span>}
              </div>
            </div>
          </div>
          
          <AnimatePresence>
            {popoverOpen && (
              <motion.div
                initial={{ opacity: 0, y: 5, scale: 0.95 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={{ opacity: 0, y: 5, scale: 0.95 }}
                className="absolute left-0 bottom-full mb-2 w-max max-w-[200px] z-[100] bg-surface-solid border border-border-default shadow-xl p-3 rounded-xl"
                onClick={e => e.stopPropagation()}
              >
                <div className="text-xs font-bold text-text-secondary mb-2">规则生效地点：</div>
                <div className="flex flex-wrap gap-1.5">
                  {displayLocations.map((loc, i) => (
                    <span key={i} className="bg-gray-100 text-text-primary text-xs px-2 py-1 rounded-md">{loc}</span>
                  ))}
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Right: Actions */}
        {(onToggle || onEdit || onDelete) && (
          <div className="flex items-center gap-1.5 shrink-0">
            {onToggle && (
              <button 
                onClick={() => onToggle(rule)}
                className={`p-1.5 rounded-full transition-colors flex items-center justify-center ${rule.enabled ? 'bg-orange-50 text-orange-500 hover:bg-orange-100' : 'bg-green-50 text-green-500 hover:bg-green-100'}`}
                title={rule.enabled ? "关闭" : "开启"}
              >
                {rule.enabled ? <PowerOff className="w-4 h-4" /> : <Power className="w-4 h-4" />}
              </button>
            )}
            {onEdit && (
              <button 
                onClick={() => onEdit(rule)}
                className="p-1.5 bg-blue-50 text-blue-500 hover:bg-blue-100 rounded-full transition-colors flex items-center justify-center"
                title="修改"
              >
                <Edit3 className="w-4 h-4" />
              </button>
            )}
            {onDelete && (
              <button 
                onClick={() => onDelete(rule.id)}
                className="p-1.5 bg-rose-50 text-rose-500 hover:bg-rose-100 rounded-full transition-colors flex items-center justify-center"
                title="删除"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            )}
          </div>
        )}
      </div>
    </Card>
  );
};
