import { useEffect } from 'react';
import { getBuildingTextColor } from '../状态栏/src/data';
import { useDraggableScroll } from '../状态栏/src/hooks/useDraggableScroll';
import { CampusBuilding } from '../状态栏/src/types';

const GRID_WIDTH = 32;
const GRID_HEIGHT = 31;
const CELL_SIZE = 60;
const GAP = 6;
const PADDING = 16;
const MAP_WIDTH = GRID_WIDTH * CELL_SIZE + (GRID_WIDTH - 1) * GAP + PADDING * 2;
const MAP_HEIGHT = GRID_HEIGHT * CELL_SIZE + (GRID_HEIGHT - 1) * GAP + PADDING * 2;
const ZOOM = 0.18 * 1.3;

export function CampusMapPreview({
  buildings,
  loading,
  heightClass = 'h-[420px]',
  hint,
  showHint = true,
}: {
  buildings: CampusBuilding[];
  loading?: boolean;
  heightClass?: string;
  hint?: string;
  showHint?: boolean;
}) {
  const dragProps = useDraggableScroll<HTMLDivElement>();

  useEffect(() => {
    const timer = window.setTimeout(() => {
      const container = dragProps.ref.current;
      if (!container) return;
      container.scrollTop = Math.max(
        0,
        (container.scrollHeight - container.clientHeight) / 2 + 2 * (CELL_SIZE + GAP) * ZOOM,
      );
      container.scrollLeft = Math.max(0, (container.scrollWidth - container.clientWidth) / 2);
    }, 50);
    return () => window.clearTimeout(timer);
  }, [dragProps.ref, buildings]);

  return (
    <div className="rounded-2xl border border-white/80 bg-white/70 overflow-hidden">
      {loading && (
        <div className="px-3.5 py-2 border-b border-border-default/60">
          <span className="text-[10px] text-text-secondary">正在同步布局…</span>
        </div>
      )}
      <div className={`${heightClass} overflow-auto hide-scrollbar bg-[#e2e8f0]`} {...dragProps} ref={dragProps.ref}>
        <div className="w-max h-max min-w-full min-h-full flex items-center justify-center p-6">
          <div className="relative" style={{ width: MAP_WIDTH * ZOOM, height: MAP_HEIGHT * ZOOM }}>
            <div
              className="relative rounded-3xl shadow-[0_12px_28px_rgba(0,0,0,0.12)] origin-top-left overflow-hidden bg-[#E8F5E9]"
              style={{ width: MAP_WIDTH, height: MAP_HEIGHT, transform: `scale(${ZOOM})` }}
            >
              <div
                className="absolute bg-[#FDFBF7] pointer-events-none z-[1] border-x-[4px] border-dashed border-[#A38980]"
                style={{
                  left: PADDING + 15 * (CELL_SIZE + GAP),
                  top: PADDING + 2 * (CELL_SIZE + GAP),
                  width: 2 * CELL_SIZE + GAP,
                  height: (GRID_HEIGHT - 4) * (CELL_SIZE + GAP) - GAP,
                }}
              />
              {[8, 15, 22].map(y => (
                <div
                  key={y}
                  className="absolute bg-[#FDFBF7] pointer-events-none z-[1] border-y-[4px] border-dashed border-[#A38980]"
                  style={{
                    left: PADDING + 2 * (CELL_SIZE + GAP),
                    top: PADDING + y * (CELL_SIZE + GAP),
                    width: (GRID_WIDTH - 4) * (CELL_SIZE + GAP) - GAP,
                    height: CELL_SIZE,
                  }}
                />
              ))}
              <div
                className="absolute bg-white/50 border border-slate-300/60 pointer-events-none z-10 rounded-t-2xl"
                style={{
                  left: PADDING,
                  top: PADDING,
                  width: GRID_WIDTH * CELL_SIZE + (GRID_WIDTH - 1) * GAP,
                  height: 2 * CELL_SIZE + GAP,
                }}
              />
              <div
                className="absolute bg-white/50 border-l border-r border-slate-300/60 pointer-events-none z-10"
                style={{
                  left: PADDING,
                  top: PADDING + 2 * (CELL_SIZE + GAP),
                  width: 2 * CELL_SIZE + GAP,
                  height: (GRID_HEIGHT - 4) * (CELL_SIZE + GAP) - GAP,
                }}
              />
              <div
                className="absolute bg-white/50 border-l border-r border-slate-300/60 pointer-events-none z-10"
                style={{
                  left: PADDING + (GRID_WIDTH - 2) * (CELL_SIZE + GAP),
                  top: PADDING + 2 * (CELL_SIZE + GAP),
                  width: 2 * CELL_SIZE + GAP,
                  height: (GRID_HEIGHT - 4) * (CELL_SIZE + GAP) - GAP,
                }}
              />
              <div
                className="absolute bg-white/50 border border-slate-300/60 pointer-events-none z-10 rounded-bl-2xl"
                style={{
                  left: PADDING,
                  top: PADDING + (GRID_HEIGHT - 2) * (CELL_SIZE + GAP),
                  width: 14 * CELL_SIZE + 13 * GAP,
                  height: 2 * CELL_SIZE + GAP,
                }}
              />
              <div
                className="absolute bg-[#FDFBF7] border-t-2 border-b-2 border-amber-300/60 pointer-events-none z-10"
                style={{
                  left: PADDING + 14 * (CELL_SIZE + GAP),
                  top: PADDING + (GRID_HEIGHT - 2) * (CELL_SIZE + GAP),
                  width: 4 * CELL_SIZE + 3 * GAP,
                  height: 2 * CELL_SIZE + GAP,
                }}
              />
              <div
                className="absolute bg-white/50 border border-slate-300/60 pointer-events-none z-10 rounded-br-2xl"
                style={{
                  left: PADDING + 18 * (CELL_SIZE + GAP),
                  top: PADDING + (GRID_HEIGHT - 2) * (CELL_SIZE + GAP),
                  width: 14 * CELL_SIZE + 13 * GAP,
                  height: 2 * CELL_SIZE + GAP,
                }}
              />
              {buildings.map(building => (
                <div
                  key={building.id}
                  className={`absolute rounded-2xl shadow-xl flex items-center justify-center text-center font-bold ${building.color} border-4 pointer-events-none ${building.id === 'gate' ? 'z-20' : 'z-10'}`}
                  style={{
                    left: PADDING + building.x * (CELL_SIZE + GAP),
                    top: PADDING + building.y * (CELL_SIZE + GAP),
                    width: building.width * CELL_SIZE + (building.width - 1) * GAP,
                    height: building.height * CELL_SIZE + (building.height - 1) * GAP,
                  }}
                >
                  <span
                    className="px-2 py-1 text-3xl font-black tracking-wide whitespace-nowrap"
                    style={{ color: getBuildingTextColor(building) }}
                  >
                    {building.name}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
      {showHint && (
        <p className="px-3.5 py-2 text-[11px] text-text-secondary">
          {hint || '可拖动查看完整布局。切换校园类型或特性后，会同步世界书 initvar 与 MVU 建筑。'}
        </p>
      )}
    </div>
  );
}
