import { ChevronLeft, Send, Users } from 'lucide-react';
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { Character, ChatGroup, ChatMessageItem, Player } from '../../types';
import { fillTavernInput } from '../../utils/fillTavernInput';
import { formatForumRelativeTime } from '../../utils/forumParser';
import { FullScreenModal } from '../ui/Modal';
import { showToast } from '../ui/Toast';

interface ChatScreenProps {
  type: 'dm' | 'group';
  targetName: string;
  player: Player;
  characters: Character[];
  group?: ChatGroup;
  messages: ChatMessageItem[];
  nowTs: number;
  onClose: () => void;
  onAvatarClick?: (character: Character) => void;
}

function Avatar({ name, src, onClick }: { name: string; src?: string | null; onClick?: () => void }) {
  return (
    <button
      type="button"
      onClick={event => {
        event.stopPropagation();
        onClick?.();
      }}
      className={`w-10 h-10 rounded-[8px] overflow-hidden shrink-0 bg-pink-100 flex items-center justify-center text-pink-500 font-bold border border-border-default ${onClick ? 'cursor-pointer' : 'cursor-default'}`}
    >
      {src ? <img src={src} alt={name} className="w-full h-full object-cover" /> : name[0]}
    </button>
  );
}

export function ChatScreen({
  type,
  targetName,
  player,
  characters,
  group,
  messages,
  nowTs,
  onClose,
  onAvatarClick,
}: ChatScreenProps) {
  const [draft, setDraft] = useState('');
  const [pending, setPending] = useState<ChatMessageItem[]>([]);
  const listRef = useRef<HTMLDivElement>(null);
  const playerName = player.name || '我';

  const visibleMessages = useMemo(() => {
    const remaining = pending.filter(
      item => !messages.some(message => message.content === item.content && message.senderName === item.senderName),
    );
    return [...messages, ...remaining];
  }, [messages, pending]);

  const jumpToBottom = () => {
    const el = listRef.current;
    if (!el) return;
    el.scrollTop = el.scrollHeight;
  };

  useLayoutEffect(() => {
    jumpToBottom();
  }, [targetName, visibleMessages.length]);

  useEffect(() => {
    jumpToBottom();
    const frame = window.requestAnimationFrame(jumpToBottom);
    const timer = window.setTimeout(jumpToBottom, 320);
    return () => {
      window.cancelAnimationFrame(frame);
      window.clearTimeout(timer);
    };
  }, [targetName, visibleMessages.length]);

  const findCharacter = (name: string) => characters.find(item => item.name === name || item.nickname === name);

  const handleSend = () => {
    const text = draft.trim();
    if (!text) return;
    const command =
      type === 'group' ? `在群聊「${targetName}」中发送消息：${text}` : `给「${targetName}」发私聊：${text}`;
    if (!fillTavernInput(command)) {
      showToast('写入输入栏失败', 'error');
      return;
    }
    setPending(prev => [
      ...prev,
      {
        id: `pending-${Date.now()}`,
        senderName: playerName,
        content: text,
        timestamp: nowTs,
        pending: true,
      },
    ]);
    setDraft('');
    showToast('已写入输入栏，发送后才会更新聊天', 'success');
  };

  return (
    <FullScreenModal isOpen={true} className="z-[90] bg-[#f6f7fb]">
      <div className="px-4 py-3 border-b border-border-default bg-white/80 backdrop-blur-md flex items-center gap-3 shrink-0">
        <button onClick={onClose} className="w-9 h-9 rounded-full bg-gray-50 flex items-center justify-center">
          <ChevronLeft className="w-5 h-5 text-text-primary" />
        </button>
        <div className="flex-1 min-w-0">
          <div className="font-bold text-text-primary truncate">{targetName}</div>
          <div className="text-[11px] text-text-secondary truncate">
            {type === 'group'
              ? `${group?.memberNames.length || 0} 人 · ${group?.summary || '校园群聊'}`
              : findCharacter(targetName)?.identity || '私聊'}
          </div>
        </div>
        {type === 'group' ? <Users className="w-5 h-5 text-text-secondary" /> : null}
      </div>

      <div ref={listRef} className="flex-1 min-h-0 overflow-y-auto px-4 py-4 space-y-3 hide-scrollbar">
        {visibleMessages.map(message => {
          const mine = message.senderName === playerName;
          const character = findCharacter(message.senderName);
          const avatar = (
            <Avatar
              name={mine ? playerName : message.senderName}
              src={mine ? player.avatar : character?.avatar}
              onClick={!mine && character ? () => onAvatarClick?.(character) : undefined}
            />
          );
          return (
            <div key={message.id} className={`flex items-start gap-2 ${mine ? 'flex-row-reverse' : 'flex-row'}`}>
              {avatar}
              <div className={`max-w-[75%] ${mine ? 'items-end' : 'items-start'} flex flex-col gap-1`}>
                {type === 'group' && !mine && (
                  <div className="text-[10px] text-text-secondary px-1">
                    {character?.nickname || message.senderName}
                  </div>
                )}
                <div
                  className={`px-3 py-2 rounded-2xl text-sm leading-relaxed ${mine ? 'bg-[#95ec69] text-[#111] rounded-tr-sm' : 'bg-white text-text-primary rounded-tl-sm border border-border-default'}`}
                >
                  {message.content}
                </div>
                <div className="text-[10px] text-text-secondary px-1">
                  {message.pending ? '待发送' : formatForumRelativeTime(message.timestamp, nowTs)}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <div className="px-3 py-2 bg-white/90 border-t border-border-default shrink-0">
        <div className="rounded-2xl border border-border-default bg-white px-3 py-1.5 flex items-end gap-2">
          <textarea
            value={draft}
            onChange={event => setDraft(event.target.value)}
            rows={1}
            placeholder="输入聊天内容..."
            className="flex-1 bg-transparent resize-none outline-none text-sm py-2 max-h-24"
          />
          <button
            onClick={handleSend}
            className="w-9 h-9 rounded-full bg-pink-500 text-white flex items-center justify-center shrink-0"
          >
            <Send className="w-4 h-4" />
          </button>
        </div>
      </div>
    </FullScreenModal>
  );
}
