import { Pencil, Plus, Trash2 } from 'lucide-react';
import { useMemo, useState } from 'react';
import { ConfirmDialog } from '../状态栏/src/components/ui/ConfirmDialog';
import { CenterModal } from '../状态栏/src/components/ui/Modal';
import {
  CustomCampusTrait,
  CustomCampusType,
  loadCustomCampusTraitsByType,
  loadCustomCampusTypes,
  loadWorldviewOverrides,
  saveCustomCampusCatalog,
  saveWorldviewOverrides,
} from './campusCatalog';
import { CAMPUS_TRAITS, CAMPUS_TYPES, CampusTrait, CampusType, getInstitutionLabel, getTraitLabel } from './constants';
import { CampusMapEditor } from './CampusMapEditor';
import {
  campusLayoutToPreviewBuildings,
  cloneCampusLayout,
  cloneNormalYouthCampusLayout,
  previewBuildingsToLayout,
} from './campusLayout';
import { formatCampusWorldbook } from './playerArchive';

interface CampusInfoSelectorProps {
  campusType: string;
  campusTraits: string[];
  onChange: (type: string, traits: string[], worldview: string) => void;
}

const INCOMPLETE_CAMPUS_TYPES = new Set<CampusType>(['玄幻修仙', '魔法学院']);

function isBuiltinType(type: string): type is CampusType {
  return CAMPUS_TYPES.includes(type as CampusType);
}

function createTraitDraft(): CustomCampusTrait {
  return {
    id: `custom-trait-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
    name: '',
    worldview: '',
    mapLayout: cloneNormalYouthCampusLayout(),
  };
}

function worldviewKey(type: string, traitId: string) {
  return `${type}::${traitId}`;
}

function WorldviewPreview({ content, onSave }: { content: string; onSave: (next: string) => void }) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(content);

  const openEditor = () => {
    setDraft(content);
    setEditing(true);
  };

  return (
    <>
      <div className="w-full text-left rounded-2xl border px-3.5 py-3 bg-pink-50 border-pink-300 shadow-sm">
        <div className="flex items-center justify-between gap-2">
          <span className="text-sm font-bold text-pink-700">世界观内容</span>
          <button
            type="button"
            onClick={openEditor}
            className="inline-flex items-center gap-1 text-xs font-bold text-pink-500"
          >
            <Pencil className="w-3.5 h-3.5" />
            编辑
          </button>
        </div>
        <p className="mt-2 text-xs leading-5 text-text-secondary line-clamp-3 whitespace-pre-wrap">
          {content}
        </p>
      </div>
      <CenterModal
        isOpen={editing}
        onClose={() => setEditing(false)}
        className="glass w-[300px] max-h-[80vh] rounded-[20px] border border-white/50 shadow-xl p-4 overflow-y-auto hide-scrollbar"
      >
        <h3 className="text-base font-bold text-text-primary mb-3">编辑世界观内容</h3>
        <textarea
          value={draft}
          onChange={event => setDraft(event.target.value)}
          rows={12}
          className="w-full rounded-xl px-3 py-2 bg-white border border-border-default text-[11px] leading-5 outline-none focus:ring-2 focus:ring-pink-200 resize-none"
        />
        <div className="flex gap-2 mt-4">
          <button
            type="button"
            onClick={() => setEditing(false)}
            className="flex-1 py-2.5 text-sm font-bold rounded-xl bg-white border border-border-default text-text-secondary"
          >
            取消
          </button>
          <button
            type="button"
            onClick={() => {
              onSave(draft);
              setEditing(false);
            }}
            className="flex-1 py-2.5 text-sm font-bold rounded-xl text-white bg-gradient-to-r from-pink-400 to-rose-400"
          >
            保存
          </button>
        </div>
      </CenterModal>
    </>
  );
}

function OptionChip({ selected, label, onClick }: { selected: boolean; label: string; onClick: () => void }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`px-3.5 py-2 rounded-xl text-sm font-bold border transition-all ${
        selected
          ? 'bg-gradient-to-r from-pink-400 to-rose-400 text-white border-pink-400 shadow-md shadow-pink-200'
          : 'bg-white/70 text-text-secondary border-border-default hover:border-pink-200 hover:text-pink-500'
      }`}
    >
      {label}
    </button>
  );
}

export function CampusInfoSelector({ campusType, campusTraits, onChange }: CampusInfoSelectorProps) {
  const [customTypes, setCustomTypes] = useState<CustomCampusType[]>(() => loadCustomCampusTypes());
  const [customTraitsByType, setCustomTraitsByType] = useState<Record<string, CustomCampusTrait[]>>(
    () => loadCustomCampusTraitsByType(),
  );
  const [creating, setCreating] = useState(false);
  const [editingTypeId, setEditingTypeId] = useState<string | null>(null);
  const [draftName, setDraftName] = useState('');
  const [draftTraits, setDraftTraits] = useState<CustomCampusTrait[]>([createTraitDraft()]);
  const [expandedTraitId, setExpandedTraitId] = useState<string | null>(null);
  const [worldviewOverrides, setWorldviewOverrides] = useState<Record<string, string>>(
    () => loadWorldviewOverrides(),
  );
  const [pendingTypeId, setPendingTypeId] = useState<CampusType | null>(null);
  const [editingMapTraitId, setEditingMapTraitId] = useState<string | null>(null);

  const selectedTraitId = campusTraits[0] || '';
  const selectedCustomType = customTypes.find(item => item.id === campusType);
  const customTraits = customTraitsByType[campusType] || [];
  const selectedCustomTrait = customTraits.find(item => item.id === selectedTraitId);
  const canSaveCustom = draftName.trim().length > 0 && draftTraits.some(item => item.name.trim());

  const typeOptions = useMemo(
    () => [
      ...CAMPUS_TYPES.map(type => ({ id: type, name: type, custom: false })),
      ...customTypes.map(type => ({ id: type.id, name: type.name, custom: true })),
    ],
    [customTypes],
  );

  const applyType = (typeId: string, custom: boolean) => {
    if (!custom) {
      onChange(typeId, ['全女'], getBuiltinWorldview(typeId as CampusType, '全女'));
      return;
    }
    const first = customTraitsByType[typeId]?.[0];
    onChange(typeId, first ? [first.id] : [], first?.worldview || '');
  };

  const persist = (nextTypes: CustomCampusType[], nextTraits: Record<string, CustomCampusTrait[]>) => {
    setCustomTypes(nextTypes);
    setCustomTraitsByType(nextTraits);
    saveCustomCampusCatalog(nextTypes, nextTraits);
  };

  const getBuiltinWorldview = (type: CampusType, trait: CampusTrait) =>
    worldviewOverrides[worldviewKey(type, trait)] ?? formatCampusWorldbook(type, trait);

  const saveBuiltinWorldview = (type: CampusType, trait: CampusTrait, next: string) => {
    const overrides = { ...worldviewOverrides, [worldviewKey(type, trait)]: next };
    setWorldviewOverrides(overrides);
    saveWorldviewOverrides(overrides);
    onChange(type, [trait], next);
  };

  const saveCustomWorldview = (traitId: string, next: string) => {
    const traits = (customTraitsByType[campusType] || []).map(item =>
      item.id === traitId ? { ...item, worldview: next } : item,
    );
    persist(customTypes, { ...customTraitsByType, [campusType]: traits });
    onChange(campusType, [traitId], next);
  };

  const openCreate = () => {
    const first = createTraitDraft();
    setEditingTypeId(null);
    setDraftName('');
    setDraftTraits([first]);
    setExpandedTraitId(first.id);
    setCreating(true);
  };

  const openEdit = (typeId: string) => {
    const type = customTypes.find(item => item.id === typeId);
    if (!type) return;
    const traits = customTraitsByType[typeId]?.length ? customTraitsByType[typeId] : [createTraitDraft()];
    setEditingTypeId(typeId);
    setDraftName(type.name);
    setDraftTraits(traits.map(item => ({
      ...item,
      mapLayout: cloneCampusLayout(item.mapLayout || cloneNormalYouthCampusLayout()),
    })));
    setExpandedTraitId(traits[0]?.id || null);
    setCreating(true);
  };

  const handleSaveCustom = () => {
    const name = draftName.trim();
    const traits = draftTraits
      .map(item => ({
        ...item,
        name: item.name.trim(),
        worldview: item.worldview.trim(),
        mapLayout: cloneCampusLayout(item.mapLayout || cloneNormalYouthCampusLayout()),
      }))
      .filter(item => item.name);
    if (!name || traits.length === 0) return;
    const typeId = editingTypeId || `custom-type-${Date.now().toString(36)}`;
    const nextType = { id: typeId, name };
    const nextTypes = editingTypeId
      ? customTypes.map(item => (item.id === typeId ? nextType : item))
      : [...customTypes, nextType];
    persist(nextTypes, { ...customTraitsByType, [typeId]: traits });
    const currentTrait = traits.find(item => item.id === expandedTraitId) || traits[0];
    onChange(typeId, [currentTrait.id], currentTrait.worldview);
    setCreating(false);
  };

  const editingMapBuildings = useMemo(
    () =>
      campusLayoutToPreviewBuildings(
        draftTraits.find(item => item.id === editingMapTraitId)?.mapLayout || cloneNormalYouthCampusLayout(),
      ),
    [draftTraits, editingMapTraitId],
  );

  return (
    <div className="space-y-4">
      <div>
        <p className="text-xs font-bold text-text-secondary mb-2">校园类型</p>
        <div className="flex flex-wrap gap-2">
          {typeOptions.map(option => (
            <OptionChip
              key={option.id}
              selected={campusType === option.id}
              label={option.name}
              onClick={() => {
                if (campusType === option.id) return;
                if (!option.custom && INCOMPLETE_CAMPUS_TYPES.has(option.id as CampusType)) {
                  setPendingTypeId(option.id as CampusType);
                  return;
                }
                applyType(option.id, option.custom);
              }}
            />
          ))}
        </div>
      </div>

      {isBuiltinType(campusType) && (
        <div>
          <p className="text-xs font-bold text-text-secondary mb-2">{getInstitutionLabel(campusType)}特性</p>
          <div className="flex flex-wrap gap-2">
            {CAMPUS_TRAITS.map(trait => (
              <OptionChip
                key={trait}
                selected={selectedTraitId === trait}
                label={getTraitLabel(campusType, trait)}
                onClick={() => onChange(campusType, [trait], getBuiltinWorldview(campusType, trait))}
              />
            ))}
          </div>
        </div>
      )}

      {selectedCustomType && (
        <div>
          <div className="flex items-center justify-between mb-2">
            <p className="text-xs font-bold text-text-secondary">{selectedCustomType.name}特性</p>
            <button type="button" onClick={() => openEdit(selectedCustomType.id)} className="inline-flex items-center gap-1 text-xs font-bold text-pink-500">
              <Pencil className="w-3.5 h-3.5" />
              编辑类型
            </button>
          </div>
          {customTraits.length > 0 ? (
            <div className="flex flex-wrap gap-2">
              {customTraits.map(trait => (
                <OptionChip
                  key={trait.id}
                  selected={selectedTraitId === trait.id}
                  label={trait.name}
                  onClick={() => onChange(campusType, [trait.id], trait.worldview)}
                />
              ))}
            </div>
          ) : (
            <p className="text-xs text-text-secondary rounded-2xl border border-dashed border-border-default bg-white/60 p-3">
              这个自定义类型还没有校园特性，点击「编辑类型」在浮窗中添加。
            </p>
          )}
        </div>
      )}

      {isBuiltinType(campusType) && CAMPUS_TRAITS.includes(selectedTraitId as CampusTrait) && (
        <WorldviewPreview
          key={`${campusType}-${selectedTraitId}`}
          content={getBuiltinWorldview(campusType, selectedTraitId as CampusTrait)}
          onSave={next => saveBuiltinWorldview(campusType, selectedTraitId as CampusTrait, next)}
        />
      )}

      {selectedCustomTrait && (
        <WorldviewPreview
          key={selectedCustomTrait.id}
          content={selectedCustomTrait.worldview || '这个特性还没有填写世界观内容。'}
          onSave={next => saveCustomWorldview(selectedCustomTrait.id, next)}
        />
      )}

      <ConfirmDialog
        open={Boolean(pendingTypeId)}
        title="校园类型提示"
        message="该校园类型的世界书与相关角色、建筑暂未做完整适配，可能有OC情况出现"
        confirmText="我已知晓"
        onClose={() => setPendingTypeId(null)}
        onConfirm={() => {
          if (!pendingTypeId) return;
          applyType(pendingTypeId, false);
          setPendingTypeId(null);
        }}
      />

      <button
        type="button"
        onClick={openCreate}
        className="w-full py-2.5 rounded-2xl border-2 border-dashed border-pink-200 text-pink-500 font-bold text-sm flex items-center justify-center gap-1 bg-pink-50/60 hover:bg-pink-50"
      >
        <Plus className="w-4 h-4" />
        自定义校园类型
      </button>

      <CenterModal
        isOpen={creating}
        onClose={() => setCreating(false)}
        className="glass w-[300px] max-h-[80vh] rounded-[20px] border border-white/50 shadow-xl p-4 overflow-y-auto hide-scrollbar"
      >
        <h3 className="text-base font-bold text-text-primary mb-3">{editingTypeId ? '编辑校园类型' : '自定义校园类型'}</h3>
        <label className="block mb-3">
          <span className="text-xs font-bold text-text-secondary mb-1.5 block">校园类型名称</span>
          <input
            value={draftName}
            onChange={event => setDraftName(event.target.value)}
            placeholder="如：末日求生校园"
            className="w-full h-10 rounded-xl px-3 bg-white border border-border-default outline-none focus:ring-2 focus:ring-pink-200"
          />
        </label>
        <div className="mb-3">
          <p className="text-xs font-bold text-text-secondary mb-1.5">该类型下的校园特性</p>
          <div className="space-y-2">
            {draftTraits.map((trait, index) => {
              const expanded = expandedTraitId === trait.id;
              return (
                <div key={trait.id} className="rounded-xl border border-border-default bg-white p-3">
                  <label className="block">
                    <span className="text-xs font-bold text-text-secondary mb-1.5 block">
                      特性名称 {draftTraits.length > 1 ? index + 1 : ''}
                    </span>
                    <div className="flex items-center gap-2">
                      <input
                        value={trait.name}
                        onFocus={() => setExpandedTraitId(trait.id)}
                        onChange={event => {
                          const name = event.target.value;
                          setDraftTraits(prev => prev.map(item => (item.id === trait.id ? { ...item, name } : item)));
                        }}
                        placeholder="如：封闭隔离"
                        className="flex-1 h-10 rounded-xl px-3 bg-white border border-border-default outline-none focus:ring-2 focus:ring-pink-200"
                      />
                      {draftTraits.length > 1 && (
                        <button
                          type="button"
                          onClick={() => {
                            const next = draftTraits.filter(item => item.id !== trait.id);
                            setDraftTraits(next);
                            if (expandedTraitId === trait.id) setExpandedTraitId(next[0]?.id || null);
                          }}
                          className="w-10 h-10 rounded-xl bg-white border border-border-default text-text-secondary flex items-center justify-center"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      )}
                    </div>
                  </label>
                  {expanded && (
                    <div className="mt-3 space-y-3">
                      <label className="block">
                        <span className="text-xs font-bold text-text-secondary mb-1.5 block">世界观内容</span>
                        <textarea
                          value={trait.worldview}
                          onChange={event => {
                            const worldview = event.target.value;
                            setDraftTraits(prev => prev.map(item => (item.id === trait.id ? { ...item, worldview } : item)));
                          }}
                          rows={4}
                          placeholder="描述这个校园类型下，该特性对应的世界观"
                          className="w-full rounded-xl px-3 py-2 bg-white border border-border-default outline-none focus:ring-2 focus:ring-pink-200 resize-none"
                        />
                      </label>
                      <button
                        type="button"
                        onClick={() => setEditingMapTraitId(trait.id)}
                        className="w-full py-2.5 rounded-xl text-sm font-bold text-pink-500 bg-pink-50 border border-pink-200"
                      >
                        配置该特性地图
                      </button>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
          <button
            type="button"
            onClick={() => {
              const next = createTraitDraft();
              setDraftTraits(prev => [...prev, next]);
              setExpandedTraitId(next.id);
            }}
            className="mt-2 w-full py-2.5 rounded-xl text-sm font-bold text-white bg-gradient-to-r from-pink-400 to-rose-400 flex items-center justify-center gap-1"
          >
            <Plus className="w-4 h-4" />
            新增校园特性
          </button>
        </div>
        <div className="flex gap-2">
          <button type="button" onClick={() => setCreating(false)} className="flex-1 py-2.5 text-sm font-bold rounded-xl bg-white border border-border-default text-text-secondary">
            取消
          </button>
          <button
            type="button"
            disabled={!canSaveCustom}
            onClick={handleSaveCustom}
            className="flex-1 py-2.5 text-sm font-bold rounded-xl text-white bg-gradient-to-r from-pink-400 to-rose-400 disabled:opacity-50"
          >
            保存
          </button>
        </div>
      </CenterModal>
      <CampusMapEditor
        open={Boolean(editingMapTraitId)}
        buildings={editingMapBuildings}
        onClose={() => setEditingMapTraitId(null)}
        onSave={nextBuildings => {
          const layout = previewBuildingsToLayout(nextBuildings);
          setDraftTraits(prev =>
            prev.map(item => (item.id === editingMapTraitId ? { ...item, mapLayout: layout } : item)),
          );
          setEditingMapTraitId(null);
        }}
      />
    </div>
  );
}