import { ClassmateArchive, parseClassmateProfile, parseRoleArchiveName } from '../../../游戏开局/classmates';
import { resolveSakuraWorldbookName } from '../../../游戏开局/playerArchive';

export async function loadWorkshopCharacters(): Promise<(ClassmateArchive & { enabled: boolean })[]> {
  const worldbookName = resolveSakuraWorldbookName();
  if (!worldbookName) return [];
  try {
    const worldbook = await getWorldbook(worldbookName);
    return worldbook
      .map(entry => {
        if (!parseRoleArchiveName(entry.name)) return null;
        return { ...parseClassmateProfile(entry.name, entry.content, false, entry.uid), enabled: entry.enabled !== false };
      })
      .filter((item): item is ClassmateArchive & { enabled: boolean } => Boolean(item));
  } catch (error) {
    console.warn('[校园APP] 无法读取角色档案:', error);
    return [];
  }
}
